-- Sail Admin 日志、字典及菜单图标增量升级。先备份，执行一次，不重导base.sql。
CREATE TABLE IF NOT EXISTS sys_dictionary_type (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '字典类型主键编号',
    `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间，上海时区',
    `updated_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '更新时间，上海时区',
    `code` VARCHAR(64) NOT NULL COMMENT '稳定字典类型编码',
    `name` VARCHAR(64) NOT NULL COMMENT '字典类型中文名称',
    `status` INT NOT NULL DEFAULT 1 COMMENT '类型状态：1启用0停用',
    `built_in` BOOLEAN NOT NULL DEFAULT FALSE COMMENT '系统类型保护标记，编码不可修改删除',
    `remark` VARCHAR(255) COMMENT '字典类型用途说明',
    `deleted` BIGINT NOT NULL DEFAULT 0 COMMENT '逻辑删除标记：0有效，删除后等于主键id',
    UNIQUE KEY uk_dictionary_type_code (code,deleted)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统字典类型';


ALTER TABLE sys_audit ADD COLUMN `operation_type` VARCHAR(32) COMMENT '操作业务类型，字典sys_operation_type';
ALTER TABLE sys_audit ADD COLUMN `request_method` VARCHAR(16) COMMENT 'HTTP请求方式，字典sys_request_method';
ALTER TABLE sys_audit ADD COLUMN `request_url` VARCHAR(512) COMMENT '请求路径，不包含认证头和查询串';
ALTER TABLE sys_audit ADD COLUMN `request_params` TEXT COMMENT '脱敏查询参数，最多8192字符并标明截断';
ALTER TABLE sys_audit ADD COLUMN `request_body` TEXT COMMENT '脱敏JSON请求正文，文件及二进制内容不记录';
ALTER TABLE sys_audit ADD COLUMN `response_body` TEXT COMMENT '脱敏业务响应快照，最多8192字符并标明截断';
ALTER TABLE sys_audit ADD COLUMN `http_status` INT COMMENT '最终HTTP响应状态码';
ALTER TABLE sys_audit ADD COLUMN `response_code` INT COMMENT '统一业务响应码，无业务响应时为空';
ALTER TABLE sys_audit ADD COLUMN `duration_ms` BIGINT COMMENT '请求处理耗时，单位毫秒';
ALTER TABLE sys_audit ADD COLUMN `error_message` TEXT COMMENT '可定位的业务或参数错误说明，不含秘密';
ALTER TABLE sys_dictionary ADD COLUMN `color` VARCHAR(32) NOT NULL DEFAULT 'default' COMMENT '标签色：default、success、warning、error、processing';
ALTER TABLE sys_dictionary ADD COLUMN `remark` VARCHAR(255) COMMENT '字典数据说明';
ALTER TABLE sys_dictionary ADD COLUMN `is_default` BOOLEAN NOT NULL DEFAULT FALSE COMMENT '是否为此类型的默认项';
ALTER TABLE sys_dictionary ADD COLUMN `built_in` BOOLEAN NOT NULL DEFAULT FALSE COMMENT '内置业务值保护标记，标签可维护';
ALTER TABLE sys_menu ADD COLUMN icon VARCHAR(64) COMMENT 'Lucide图标名称，由菜单管理配置';
